    pub enum PetEvent {
        Changed(crate::types::Pet),
        Gone(String),
    }

    impl PetEvent {
        pub const DESCRIPTION: &'static str = r#"What happens to a pet, as it happens."#;
        pub const CHANGED_DESCRIPTION: &'static str = r#"The pet as it is now."#;
        pub const GONE_DESCRIPTION: &'static str = r#"Why the feed ended, as text."#;
    }

    impl From<PetEvent> for AxEvent {
        fn from(event: PetEvent) -> Self {
            match event {
                PetEvent::Changed(data) => AxEvent::default()
                    .event("changed")
                    .data(serde_json::to_string(&data).expect("a wire shape serializes")),
                PetEvent::Gone(data) => AxEvent::default().event("gone").data(data.to_string()),
            }
        }
    }

    fn pet_event_item() -> serde_json::Value {
        json!({
            "type": "object",
            "properties": {"event": {"type": "string"}, "data": {"type": "string"}},
            "required": ["event"],
            "oneOf": [{"properties": {"data": {"contentMediaType": "application/json", "contentSchema": json!({"$ref": "#/components/schemas/Pet"})}, "event": {"const": "changed"}}}, {"properties": {"data": {"contentMediaType": "text/plain", "contentSchema": {"type": "string"}}, "event": {"const": "gone"}}}]
        })
    }

    impl utoipa::PartialSchema for PetEvent {
        fn schema() -> utoipa::openapi::RefOr<utoipa::openapi::schema::Schema> {
            serde_json::from_value(json!({"type": "object"})).expect("the PetEvent schema is valid")
        }
    }

    impl utoipa::ToSchema for PetEvent {
        fn name() -> std::borrow::Cow<'static, str> {
            std::borrow::Cow::Borrowed("PetEventItem")
        }
        fn schemas(
            schemas: &mut Vec<(
                String,
                utoipa::openapi::RefOr<utoipa::openapi::schema::Schema>,
            )>,
        ) {
            // Registered before it is followed, and once: a type that refers back to this one would otherwise be followed for ever.
            if !schemas.iter().any(|(name, _)| name == "Pet") {
                schemas.push((
                    "Pet".to_owned(),
                    <crate::types::Pet as utoipa::PartialSchema>::schema(),
                ));
                <crate::types::Pet as utoipa::ToSchema>::schemas(schemas);
            }
        }
    }

